import { readFileSync } from "node:fs";

export type IncidentSeverity = "minor" | "major";

export interface Incident {
  // ISO timestamp of when the incident was logged.
  time: string;
  service: string;
  severity: IncidentSeverity;
  note: string;
}

const SEVERITIES: IncidentSeverity[] = ["minor", "major"];

export function loadIncidents(path = new URL("../data/incidents.json", import.meta.url)): Incident[] {
  const data = JSON.parse(readFileSync(path, "utf8")) as Incident[];
  for (const inc of data) {
    if (!SEVERITIES.includes(inc.severity)) throw new Error(`${inc.service}: unknown severity ${inc.severity}`);
    if (Number.isNaN(Date.parse(inc.time))) throw new Error(`${inc.service}: bad time ${inc.time}`);
  }
  return newestFirst(data);
}

// Descending by time, stable for ties.
export function newestFirst(incidents: Incident[]): Incident[] {
  return [...incidents].sort((a, b) => Date.parse(b.time) - Date.parse(a.time));
}
```

