import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { loadIncidents, newestFirst, type Incident } from "../src/incidents.ts";

function writeIncidents(incidents: unknown): string {
  const dir = mkdtempSync(join(tmpdir(), "incidents-"));
  const path = join(dir, "incidents.json");
  writeFileSync(path, JSON.stringify(incidents));
  return path;
}

describe("loadIncidents", () => {
  it("reads the data file and orders newest first", () => {
    const incidents = loadIncidents();
    expect(incidents.length).toBeGreaterThan(0);
    const times = incidents.map((i) => Date.parse(i.time));
    expect(times).toEqual([...times].sort((a, b) => b - a));
  });

  it("throws on an unknown severity", () => {
    const path = writeIncidents([{ time: "2026-01-01T00:00:00Z", service: "api", severity: "weird", note: "x" }]);
    expect(() => loadIncidents(path)).toThrow(/severity/);
  });

  it("throws on an unparseable time", () => {
    const path = writeIncidents([{ time: "nope", service: "api", severity: "minor", note: "x" }]);
    expect(() => loadIncidents(path)).toThrow(/time/);
  });
});

describe("newestFirst", () => {
  it("sorts descending, keeping ties stable", () => {
    const mk = (t: string, n: string): Incident => ({ time: t, service: "s", severity: "minor", note: n });
    expect(newestFirst([mk("2026-01-01T00:00:00Z", "a"), mk("2026-03-01T00:00:00Z", "b"), mk("2026-01-01T00:00:00Z", "c")]).map(i => i.note)).toEqual(["b", "a", "c"]);
  });
});
```

